1	package payflow
2	
3	import (
4		"crypto/sha256"
5		"encoding/hex"
6		"encoding/json"
7		"errors"
8		"math"
9		"os"
10		"path/filepath"
11		"syscall"
12	)
13	
14	// atomicWrite 将 v 以 JSON 原子写入 path：
15	//  1. 写入同目录临时文件并 fsync；
16	//  2. rename 覆盖目标文件（同文件系统内原子）；
17	//  3. 尽力 fsync 目录，帮助 rename 跨掉电容灾。
18	//
19	// 关键不变式：磁盘上的目标文件在任意时刻要么是完整旧内容，
20	// 要么是完整新内容（临时文件先 fsync 后改名，JSON 只写一个文档）。
21	// 进程在保存期间崩溃，重开只能看到完整的旧状态或新状态，
22	// 不会出现“扣款无记录”或“记录未扣款”。
23	func atomicWrite(path string, v any) error {
24		perm := os.FileMode(0o600)
25		data, err := json.Marshal(v)
26		if err != nil {
27			return ledgerError(ErrStorage, "encode ledger: %v", err)
28		}
29		data = append(data, '\n')
30	
31		dir := filepath.Dir(path)
32		if err := os.MkdirAll(dir, 0o700); err != nil {
33			return ledgerError(ErrStorage, "create ledger directory %s: %v", dir, err)
34		}
35	
36		tmp, err := os.CreateTemp(dir, ".ledger-*.tmp")
37		if err != nil {
38			return ledgerError(ErrStorage, "create temp file in %s: %v", dir, err)
39		}
40		tmpName := tmp.Name()
41		removeTemp := func() { _ = os.Remove(tmpName) }
42	
43		if _, err := tmp.Write(data); err != nil {
44			_ = tmp.Close()
45			removeTemp()
46			return ledgerError(ErrStorage, "write temp file: %v", err)
47		}
48		if err := tmp.Sync(); err != nil {
49			_ = tmp.Close()
50			removeTemp()
51			return ledgerError(ErrStorage, "fsync temp file: %v", err)
52		}
53		if err := tmp.Close(); err != nil {
54			removeTemp()
55			return ledgerError(ErrStorage, "close temp file: %v", err)
56		}
57		if err := os.Chmod(tmpName, perm); err != nil {
58			removeTemp()
59			return ledgerError(ErrStorage, "chmod temp file: %v", err)
60		}
61		// rename 之后新文件已完整就位。即便此后目录 fsync 失败，也不能再回滚：
62		// 回滚内存会与磁盘（已是新状态）分叉。目录 fsync 仅影响掉电后目录项的
63		// 持久性，而可能出现的两种结局（旧文件/新文件）都是完整状态。
64		if err := os.Rename(tmpName, path); err != nil {
65			removeTemp()
66			return ledgerError(ErrStorage, "rename into place: %v", err)
67		}
68		if d, err := os.Open(dir); err == nil {
69			_ = d.Sync()
70			_ = d.Close()
71		}
72		return nil
73	}
74	
75	// createExclusive 在 path 处排他地创建新账本文件，绝不覆盖任何已有路径项。
76	//
77	// 与 atomicWrite 的关键区别在最后一步：临时文件完整落盘后，用 link(2)
78	// （ATOMIC_CREATE：目标存在即失败）把它发布到 path，而不是 rename。
79	// 这使“检查路径是否占用”和“创建账本”成为内核里的同一个原子操作：
80	//   - 普通文件、目录、损坏或空文件：EEXIST，原内容逐字节不变；
81	//   - path 上是符号链接（无论其目标存在与否、指向文件还是目录）：
82	//     link 不跟随符号链接，一律 EEXIST，链接本身与其去向保持不变，
83	//     也不会顺着悬空链接把目标文件创建出来；
84	//   - 经指向目录的符号链接访问一个尚未占用的文件位置时，目录项原本
85	//     不存在，创建照常成功。
86	//
87	// 多个进程同时初始化同一尚不存在的路径时，只有一个 link 成功；
88	// 失败者拿到 EEXIST 并清理自己的临时文件，不会触碰胜出者的文件。
89	// 由于发布用的是硬链接而非 rename，胜出者磁盘上的文件从发布那一刻起
90	// 就是已 fsync 的完整内容（临时文件与 path 指向同一个 inode），
91	// 崩溃后同样只可能看到“完整新账本”或“路径不存在”，没有半成品。
92	//
93	// path 占用时返回带 ErrExists 的账本错误；其余创建/写入失败返回
94	// ErrStorage 且不留下账本文件或临时文件。
95	func createExclusive(path string, v any) error {
96		data, err := json.Marshal(v)
97		if err != nil {
98			return ledgerError(ErrStorage, "encode ledger: %v", err)
99		}
100		data = append(data, '\n')
101	
102		dir := filepath.Dir(path)
103		if err := os.MkdirAll(dir, 0o700); err != nil {
104			return ledgerError(ErrStorage, "create ledger directory %s: %v", dir, err)
105		}
106	
107		tmp, err := os.CreateTemp(dir, ".ledger-*.tmp")
108		if err != nil {
109			return ledgerError(ErrStorage, "create temp file in %s: %v", dir, err)
110		}
111		tmpName := tmp.Name()
112		removeTemp := func() { _ = os.Remove(tmpName) }
113	
114		if _, err := tmp.Write(data); err != nil {
115			_ = tmp.Close()
116			removeTemp()
117			return ledgerError(ErrStorage, "write temp file: %v", err)
118		}
119		if err := tmp.Sync(); err != nil {
120			_ = tmp.Close()
121			removeTemp()
122			return ledgerError(ErrStorage, "fsync temp file: %v", err)
123		}
124		if err := tmp.Close(); err != nil {
125			removeTemp()
126			return ledgerError(ErrStorage, "close temp file: %v", err)
127		}
128		if err := os.Chmod(tmpName, 0o600); err != nil {
129			removeTemp()
130			return ledgerError(ErrStorage, "chmod temp file: %v", err)
131		}
132	
133		// 原子排他发布：path 上存在任何路径项（含悬空/指向文件或目录的符号链接）
134		// 都返回 EEXIST，绝不替换它，也不跟随它。
135		if err := os.Link(tmpName, path); err != nil {
136			removeTemp()
137			if errors.Is(err, syscall.EEXIST) {
138				return ledgerError(ErrExists, "ledger already exists at %s", path)
139			}
140			return ledgerError(ErrStorage, "create ledger at %s: %v", path, err)
141		}
142		// path 与临时文件现在是同一个 inode；移除临时名字不影响已发布的账本。
143		removeTemp()
144		if d, err := os.Open(dir); err == nil {
145			_ = d.Sync()
146			_ = d.Close()
147		}
148		return nil
149	}
150	
151	// validateAndReplay 校验全部成功记录并从冻结的初始余额重放结算与退款：
152	// ID 唯一、序列连续、费用一致、int64 不溢出、退款只能引用此前存在的结算且
153	// 每笔结算最多退回一次、退款金额必须等于原扣款、任一时点余额非负，
154	// 且重放结果必须等于文件中的最终余额。任何不符都判定账本损坏。
155	//
156	// 结算与退款按各自成功历史交错：退款 r 只允许发生在序号 <= r.AfterSeq 的
157	// 结算之后（AfterSeq 是退款落账时结算历史的长度）。这保留了
158	// “付款 → 退款 → 再付款”的真实时间顺序，使中间余额与最终余额都可验证。
159	func validateAndReplay(initial, final map[balanceKey]int64, records []Record, refunds []RefundRecord) error {
160		// 先校验结算自身的结构不变式（余额相关的判定由后面的交错重放完成，
161		// 因为退款回收的余额允许同一笔钱被再次扣出，累计毛扣款可能超过初始余额）。
162		seen := map[string]bool{}
163		for i, r := range records {
164			if r.ID == "" {
165				return ledgerError(ErrCorrupt, "settlement %d has empty id", i)
166			}
167			if seen[r.ID] {
168				return ledgerError(ErrCorrupt, "duplicate settlement id %q", r.ID)
169			}
170			seen[r.ID] = true
171			if r.Account == "" || r.Asset == "" {
172				return ledgerError(ErrCorrupt, "settlement %q missing account or asset", r.ID)
173			}
174			if _, ok := initial[balanceKey{r.Account, r.Asset}]; !ok {
175				return ledgerError(ErrCorrupt, "settlement %q touches account/asset absent from initial balances", r.ID)
176			}
177			if r.Amount <= 0 || r.Fee < 0 || r.Charged <= 0 {
178				return ledgerError(ErrCorrupt, "settlement %q has non-positive amounts", r.ID)
179			}
180			if r.FeeBps < 0 || r.FeeBps > 10000 {
181				return ledgerError(ErrCorrupt, "settlement %q has invalid fee bps", r.ID)
182			}
183			if want := feeFor(r.Amount, r.FeeBps); want != r.Fee {
184				return ledgerError(ErrCorrupt, "settlement %q fee mismatch: file %d, want %d", r.ID, r.Fee, want)
185			}
186			if r.Charged != r.Amount+r.Fee {
187				return ledgerError(ErrCorrupt, "settlement %q charged != amount + fee", r.ID)
188			}
189			if int64(i)+1 != r.Seq {
190				return ledgerError(ErrCorrupt, "settlement %q sequence gap", r.ID)
191			}
192		}
193	
194		// 校验退款自身的不变式：字段非空、序列连续、引用的结算在退款时点已存在、
195		// 金额与去向与原结算逐字一致、每笔结算最多退回一次、退款编号全局唯一。
196		// 此外付款历史只会追加，因此按退款成功顺序（即记录顺序）看，after_seq
197		// 必须单调不减：后一笔退款落账时，已存在的结算不可能比前一笔退款时更少。
198		// 该规则针对整本账本的结算历史，与退款属于哪个账户、资产或引用哪笔付款无关。
199		seenRefund := map[string]bool{}
200		refundedBy := map[string]string{} // 结算编号 -> 首个退回它的退款编号
201		prevAfterSeq := int64(-1)
202		prevRefundID := ""
203		for i, rf := range refunds {
204			if rf.ID == "" {
205				return ledgerError(ErrCorrupt, "refund %d has empty id", i)
206			}
207			if seenRefund[rf.ID] {
208				return ledgerError(ErrCorrupt, "duplicate refund id %q", rf.ID)
209			}
210			seenRefund[rf.ID] = true
211			if rf.SettlementID == "" || rf.Reason == "" {
212				return ledgerError(ErrCorrupt, "refund %q missing settlement_id or reason", rf.ID)
213			}
214			if int64(i)+1 != rf.Seq {
215				return ledgerError(ErrCorrupt, "refund %q sequence gap", rf.ID)
216			}
217			if rf.AfterSeq < 0 || rf.AfterSeq > int64(len(records)) {
218				return ledgerError(ErrCorrupt, "refund %q references settlement outside history (after_seq=%d)", rf.ID, rf.AfterSeq)
219			}
220			if rf.AfterSeq < prevAfterSeq {
221				return ledgerError(ErrCorrupt,
222					"refund %q (seq %d) has after_seq %d, but previous refund %q (seq %d) already saw %d settlements: payment history only grows",
223					rf.ID, rf.Seq, rf.AfterSeq, prevRefundID, int64(i), prevAfterSeq)
224			}
225			prevAfterSeq = rf.AfterSeq
226			prevRefundID = rf.ID
227			var target *Record
228			for j := range records {
229				if records[j].Seq <= rf.AfterSeq && records[j].ID == rf.SettlementID {
230					target = &records[j]
231					break
232				}
233			}
234			if target == nil {
235				return ledgerError(ErrCorrupt, "refund %q references non-existent settlement %q", rf.ID, rf.SettlementID)
236			}
237			if rf.Account != target.Account || rf.Asset != target.Asset ||
238				rf.Amount != target.Amount || rf.Fee != target.Fee || rf.Charged != target.Charged {
239				return ledgerError(ErrCorrupt, "refund %q amount or destination differs from settlement %q", rf.ID, rf.SettlementID)
240			}
241			if rf.Charged <= 0 {
242				return ledgerError(ErrCorrupt, "refund %q has non-positive charged amount", rf.ID)
243			}
244			if other, dup := refundedBy[rf.SettlementID]; dup {
245				return ledgerError(ErrCorrupt, "settlement %q refunded twice: %q and %q", rf.SettlementID, other, rf.ID)
246			}
247			refundedBy[rf.SettlementID] = rf.ID
248		}
249	
250		// 按成功时间交错重放：第 s 笔结算之后落入 after_seq==s 的全部退款
251		// （退款之间按其自身序号；用分桶而非假定 after_seq 单调，以抵抗篡改数据）。
252		// net[k] 为该组合截至当前时点的“净扣款”（扣款增加、退款减少），
253		// 必须始终落在 [0, initial]，且不发生 int64 溢出。
254		buckets := make([][]int, len(records)+1) // after_seq -> refunds 下标
255		for i := range refunds {
256			buckets[refunds[i].AfterSeq] = append(buckets[refunds[i].AfterSeq], i)
257		}
258		net := make(map[balanceKey]int64)
259		for s := range records {
260			r := &records[s]
261			k := balanceKey{r.Account, r.Asset}
262			sum := net[k]
263			if r.Charged > math.MaxInt64-sum {
264				return ledgerError(ErrCorrupt, "settlement %q cumulative charges overflow int64", r.ID)
265			}
266			sum += r.Charged
267			if sum > initial[k] {
268				return ledgerError(ErrCorrupt, "settlement %q drives %s/%s negative during replay", r.ID, r.Account, r.Asset)
269			}
270			net[k] = sum
271	
272			for _, ri := range buckets[int64(s)+1] {
273				rf := &refunds[ri]
274				rk := balanceKey{rf.Account, rf.Asset}
275				cur := net[rk]
276				if rf.Charged > cur {
277					return ledgerError(ErrCorrupt, "refund %q exceeds charged amount for %s/%s at its time", rf.ID, rf.Account, rf.Asset)
278				}
279				net[rk] = cur - rf.Charged
280			}
281		}
282		// after_seq==0 的退款不可能引用任何已存在结算，前面理应已拒绝；
283		// 此处兜底，任何未被消费的退款都视为顺序损坏。
284		if len(buckets[0]) != 0 {
285			return ledgerError(ErrCorrupt, "refund %q precedes every settlement", refunds[buckets[0][0]].ID)
286		}
287	
288		// 交错重放后的末态必须与文件中的最终余额逐组合一致。
289		for k, start := range initial {
290			got := start - net[k]
291			if want, present := final[k]; !present || got != want {
292				return ledgerError(ErrCorrupt, "final balance mismatch for %s/%s: replay %d, file %v", k.account, k.asset, got, want)
293			}
294		}
295		for k := range final {
296			if _, ok := initial[k]; !ok {
297				return ledgerError(ErrCorrupt, "final balance contains %s/%s absent from initial balances", k.account, k.asset)
298			}
299		}
300		return nil
301	}
302	
303	// checksumHex 返回 data 的 sha256 十六进制摘要，作为文档完整性凭证。
304	func checksumHex(data []byte) string {
305		sum := sha256.Sum256(data)
306		return hex.EncodeToString(sum[:])
307	}
308

