75	// assertItemResult 断言一份付款结果（成功或重复）逐项等于预期：编号、状态、
76	// 说明以及完整结算记录。
77	func assertItemResult(t *testing.T, got ItemResult, wantStatus, wantReason string, want Record) {
78		t.Helper()
79		if got.ID != want.ID {
80			t.Fatalf("id=%q want %q: %+v", got.ID, want.ID, got)
81		}
82		if got.Status != wantStatus {
83			t.Fatalf("status=%s want %s: %+v", got.Status, wantStatus, got)
84		}
85		if got.Reason != wantReason {
86			t.Fatalf("reason=%q want %q: %+v", got.Reason, wantReason, got)
87		}
88		if got.Record == nil {
89			t.Fatalf("%s result must carry a record: %+v", wantStatus, got)
90		}
91		if *got.Record != want {
92			t.Fatalf("record:\n got %+v\nwant %+v", *got.Record, want)
93		}
94	}
