1	package payflow
2	
3	import (
4		"bytes"
5		"errors"
6		"fmt"
7		"os"
8		"os/exec"
9		"path/filepath"
10		"strconv"
11		"sync"
12		"testing"
13		"time"
14	)
15	
16	// 本文件回归 init 的排他创建语义：
17	//
18	//   - 同一实际目标上相互重叠的初始化请求（同进程多 goroutine、跨多进程、
19	//     一方经真实目录另一方经指向该目录的符号链接）只能有一个成功，
20	//     其余返回 ledger_exists；胜出账本的初始余额完整、不混入败者数据；
21	//   - 正常账本、损坏/空普通文件、目录、账本文件位置上的符号链接
22	//     （含悬空链接）一律按已占用拒绝，原内容与链接去向不变，
23	//     悬空链接的目标不会被顺手创建；
24	//   - 仍允许经目录符号链接在尚未占用的文件位置创建新账本；
25	//   - 非法输入优先返回 invalid_parameter 且不留任何文件；
26	//   - 创建/写入失败返回 storage_error 且不留半成品；
27	//   - 胜出账本随后产生的付款与退款不会被较晚结束的初始化重置。
28	
29	// ---- 跨进程辅助：把测试二进制本身当作会调用 CreateLedger 的独立进程 ----
30	
31	const (
32		helperEnv     = "GO_WANT_HELPER_PROCESS"
33		envLedger     = "PAYFLOW_HELPER_LEDGER"
34		envInitIdx    = "PAYFLOW_HELPER_INIT_IDX"
35		envGate       = "PAYFLOW_HELPER_GATE"
36		envResult     = "PAYFLOW_HELPER_RESULT"
37		helperBalBase = 1000
38	)
39	
40	// TestHelperCreateProcess 是“另一个独立进程”的入口：
41	// 等待闸门文件出现后，以属于本进程编号的唯一初始余额调用 CreateLedger，
42	// 把结果（ok:<编号> 或 err:<kind>）写入结果文件，并以 0/1 退出。
43	func TestHelperCreateProcess(t *testing.T) {
44		if os.Getenv(helperEnv) != "1" {
45			t.Skip("helper process only")
46		}
47		path := os.Getenv(envLedger)
48		idx, err := strconv.Atoi(os.Getenv(envInitIdx))
49		if err != nil {
50			os.Exit(2)
51		}
52		gate := os.Getenv(envGate)
53		result := os.Getenv(envResult)
54	
55		init := []BalanceInit{{
56			Account: fmt.Sprintf("winner-%02d", idx),
57			Asset:   "usdc",
58			Balance: int64(helperBalBase + idx),
59		}}
60	
61		deadline := time.Now().Add(10 * time.Second)
62		for time.Now().Before(deadline) {
63			if _, err := os.Stat(gate); err == nil {
64				break
65			}
66			time.Sleep(time.Millisecond)
67		}
68	
69		if err := CreateLedger(path, init); err != nil {
70			_ = os.WriteFile(result, []byte("err:"+KindOf(err)), 0o600)
71			os.Exit(1)
72		}
73		_ = os.WriteFile(result, []byte("ok:"+strconv.Itoa(idx)), 0o600)
74		os.Exit(0)
75	}
76	
77	type helperOutcome struct {
78		idx      int
79		exitCode int
80		result   string
81		stderr   string
82	}
83	
84	// runConcurrentCreateHelpers 启动 n 个独立进程，让它们在闸门打开后同时
85	// 对 pathFor(i) 指向的目标执行初始化，返回每个进程的退出码与结果。
86	func runConcurrentCreateHelpers(t *testing.T, n int, pathFor func(i int) string) []helperOutcome {
87		t.Helper()
88		exe, err := os.Executable()
89		if err != nil {
90			t.Fatalf("test executable: %v", err)
91		}
92		work := t.TempDir()
93		gate := filepath.Join(work, "gate")
94		resDir := filepath.Join(work, "results")
95		if err := os.Mkdir(resDir, 0o700); err != nil {
96			t.Fatal(err)
97		}
98	
99		cmds := make([]*exec.Cmd, n)
100		for i := 0; i < n; i++ {
101			resultFile := filepath.Join(resDir, fmt.Sprintf("r%d", i))
102			cmd := exec.Command(exe, "-test.run=^TestHelperCreateProcess$", "-test.count=1")
103			cmd.Env = append(os.Environ(),
104				helperEnv+"=1",
105				envLedger+"="+pathFor(i),
106				envInitIdx+"="+strconv.Itoa(i),
107				envGate+"="+gate,
108				envResult+"="+resultFile,
109			)
110			var errBuf bytes.Buffer
111			cmd.Stderr = &errBuf
112			if err := cmd.Start(); err != nil {
113				t.Fatalf("start helper %d: %v", i, err)
114			}
115			cmds[i] = cmd
116		}
117	
118		// 等所有进程都进入等待后再统一放行，最大化 init 的重叠窗口。
119		time.Sleep(150 * time.Millisecond)
120		if err := os.WriteFile(gate, []byte("go"), 0o600); err != nil {
121			t.Fatal(err)
122		}
123	
124		outcomes := make([]helperOutcome, n)
125		var wg sync.WaitGroup
126		for i, cmd := range cmds {
127			wg.Add(1)
128			go func(i int, cmd *exec.Cmd) {
129				defer wg.Done()
130				err := cmd.Wait()
131				code := 0
132				if err != nil {
133					if ee, ok := err.(*exec.ExitError); ok {
134						code = ee.ExitCode()
135					} else {
136						code = -1
137					}
138				}
139				res, _ := os.ReadFile(filepath.Join(work, "results", fmt.Sprintf("r%d", i)))
140				outcomes[i] = helperOutcome{idx: i, exitCode: code, result: string(res)}
141			}(i, cmd)
142		}
143		wg.Wait()
144		return outcomes
145	}
146	
147	// assertExactlyOneInitWinner 断言一组并发初始化恰好一个成功，
148	// 其余全部 ledger_exists（退出码 1），并返回胜出者编号。
149	func assertExactlyOneInitWinner(t *testing.T, outcomes []helperOutcome) int {
150		t.Helper()
151		winner := -1
152		for _, o := range outcomes {
153			switch {
154			case len(o.result) >= 3 && o.result[:3] == "ok:":
155				if winner != -1 {
156					t.Fatalf("two inits succeeded: %d and %d: %+v", winner, o.idx, outcomes)
157				}
158				idx, err := strconv.Atoi(o.result[3:])
159				if err != nil {
160					t.Fatalf("bad winner result %q: %v", o.result, err)
161				}
162				winner = idx
163				if o.exitCode != 0 {
164					t.Fatalf("winner %d exit code=%d", o.idx, o.exitCode)
165				}
166			case o.result == "err:"+ErrExists:
167				if o.exitCode != 1 {
168					t.Fatalf("loser %d exit code=%d want 1", o.idx, o.exitCode)
169				}
170			default:
171				t.Fatalf("helper %d unexpected outcome: code=%d result=%q", o.idx, o.exitCode, o.result)
172			}
173		}
174		if winner == -1 {
175			t.Fatalf("no init succeeded: %+v", outcomes)
176		}
177		return winner
178	}
179	
180	// assertWinnerLedgerIntact 打开账本，断言其中只有胜出者的初始余额，
181	// 没有任何其他请求的账户/资产，付款与退款历史为空。
182	func assertWinnerLedgerIntact(t *testing.T, path string, winner int) {
183		t.Helper()
184		l, err := Open(path)
185		if err != nil {
186			t.Fatalf("open winning ledger: %v", err)
187		}
188		defer l.Close()
189		snap, err := l.Query()
190		if err != nil {
191			t.Fatal(err)
192		}
193		if len(snap.Settlements) != 0 || len(snap.Refunds) != 0 {
194			t.Fatalf("fresh winning ledger must have empty history: %+v", snap)
195		}
196		wantAccount := fmt.Sprintf("winner-%02d", winner)
197		wantBalance := int64(helperBalBase + winner)
198		if len(snap.Balances) != 1 {
199			t.Fatalf("winner ledger must contain exactly one combo, got %+v", snap.Balances)
200		}
201		b := snap.Balances[0]
202		if b.Account != wantAccount || b.Asset != "usdc" || b.Balance != wantBalance {
203			t.Fatalf("winner balances=%+v want %s/usdc=%d (no mixing from losers)",
204				b, wantAccount, wantBalance)
205		}
206	}
207	
208	func assertNoTempFiles(t *testing.T, dir string) {
209		t.Helper()
210		leftover, err := filepath.Glob(filepath.Join(dir, ".ledger-*.tmp"))
211		if err != nil {
212			t.Fatal(err)
213		}
214		if len(leftover) != 0 {
215			t.Fatalf("temporary init files left behind: %v", leftover)
216		}
217	}
218	
219	// 同进程内大量 goroutine 同时初始化同一不存在的账本：恰好一个成功。
220	func TestConcurrentCreateInProcessExactlyOneWinner(t *testing.T) {
221		for round := 0; round < 20; round++ {
222			path := filepath.Join(t.TempDir(), "ledger.json")
223			const n = 16
224			var wg sync.WaitGroup
225			errs := make([]error, n)
226			var winnerMu sync.Mutex
227			winnerCount := 0
228			start := make(chan struct{})
229			for i := 0; i < n; i++ {
230				wg.Add(1)
231				go func(i int) {
232					defer wg.Done()
233					init := []BalanceInit{{
234						Account: fmt.Sprintf("g-%02d", i),
235						Asset:   "usdc",
236						Balance: int64(100 + i),
237					}}
238					<-start
239					err := CreateLedger(path, init)
240					errs[i] = err
241					if err == nil {
242						winnerMu.Lock()
243						winnerCount++
244						winnerMu.Unlock()
245					}
246				}(i)
247			}
248			close(start)
249			wg.Wait()
250	
251			if winnerCount != 1 {
252				t.Fatalf("round %d: winners=%d want exactly 1", round, winnerCount)
253			}
254			for i, err := range errs {
255				if err == nil {
256					continue
257				}
258				if KindOf(err) != ErrExists {
259					t.Fatalf("round %d loser %d: want %s, got %v", round, i, ErrExists, err)
260				}
261			}
262			assertWinnerLedgerIntactDir(t, path)
263		}
264	}
265	
266	// assertWinnerLedgerIntactDir 用于 goroutine 测试：从文件中读取出胜出账户。
267	func assertWinnerLedgerIntactDir(t *testing.T, path string) {
268		t.Helper()
269		l, err := Open(path)
270		if err != nil {
271			t.Fatalf("open: %v", err)
272		}
273		defer l.Close()
274		snap, err := l.Query()
275		if err != nil {
276			t.Fatal(err)
277		}
278		if len(snap.Balances) != 1 || len(snap.Settlements) != 0 || len(snap.Refunds) != 0 {
279			t.Fatalf("want exactly one untouched combo and empty history, got %+v", snap)
280		}
281	}
282	
283	// 跨进程同时初始化同一尚不存在的账本：恰好一个进程 initialized，
284	// 其余全部 ledger_exists；磁盘上完整保留胜出者余额。
285	func TestConcurrentCreateAcrossProcessesExactlyOneWinner(t *testing.T) {
286		for round := 0; round < 5; round++ {
287			dir := t.TempDir()
288			path := filepath.Join(dir, "ledger.json")
289			outcomes := runConcurrentCreateHelpers(t, 10, func(i int) string { return path })
290			winner := assertExactlyOneInitWinner(t, outcomes)
291			assertWinnerLedgerIntact(t, path, winner)
292			assertNoTempFiles(t, dir)
293		}
294	}
295	
296	// 一方经真实目录、另一方经指向该目录的符号链接并发初始化同一目标：
297	// 同样只能有一个胜出者，账本落在真实目录里。
298	func TestConcurrentCreateAcrossProcessesViaDirSymlink(t *testing.T) {
299		for round := 0; round < 5; round++ {
300			base := t.TempDir()
301			realDir := filepath.Join(base, "real")
302			if err := os.Mkdir(realDir, 0o700); err != nil {
303				t.Fatal(err)
304			}
305			linkDir := filepath.Join(base, "link")
306			if err := os.Symlink(realDir, linkDir); err != nil {
307				t.Fatal(err)
308			}
309			realPath := filepath.Join(realDir, "ledger.json")
310			linkPath := filepath.Join(linkDir, "ledger.json")
311	
312			outcomes := runConcurrentCreateHelpers(t, 10, func(i int) string {
313				if i%2 == 0 {
314					return realPath
315				}
316				return linkPath
317			})
318			winner := assertExactlyOneInitWinner(t, outcomes)
319			// 账本必须只存在于真实目录中（符号链接本身仍是目录链接）。
320			if fi, err := os.Lstat(linkDir); err != nil || fi.Mode()&os.ModeSymlink == 0 {
321				t.Fatalf("directory symlink must remain a symlink: %v", err)
322			}
323			assertWinnerLedgerIntact(t, realPath, winner)
324			assertWinnerLedgerIntact(t, linkPath, winner)
325			assertNoTempFiles(t, realDir)
326		}
327	}
328	
329	// 已占用路径矩阵：正常账本、空/损坏普通文件、目录、账本位置上的各种
330	// 符号链接都拒绝初始化；原内容与链接保持不变。
331	func TestCreateRejectsOccupiedPaths(t *testing.T) {
332		other := []BalanceInit{{Account: "zz", Asset: "eth", Balance: 1}}
333	
334		// 1. 已有正常账本：拒绝且逐字节不变。
335		existing := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 500}})
336		before, err := os.ReadFile(existing)
337		if err != nil {
338			t.Fatal(err)
339		}
340		if err := CreateLedger(existing, other); KindOf(err) != ErrExists {
341			t.Fatalf("existing ledger: want %s, got %v", ErrExists, err)
342		}
343		after, err := os.ReadFile(existing)
344		if err != nil {
345			t.Fatal(err)
346		}
347		if !bytes.Equal(before, after) {
348			t.Fatalf("rejected init must not rewrite the existing ledger")
349		}
350	
351		dir := t.TempDir()
352	
353		// 2. 空普通文件。
354		empty := filepath.Join(dir, "empty.json")
355		if err := os.WriteFile(empty, nil, 0o600); err != nil {
356			t.Fatal(err)
357		}
358		if err := CreateLedger(empty, other); KindOf(err) != ErrExists {
359			t.Fatalf("empty file: want %s, got %v", ErrExists, err)
360		}
361		if fi, err := os.Stat(empty); err != nil || fi.Size() != 0 || fi.IsDir() {
362			t.Fatalf("empty file must remain an empty regular file: %+v %v", fi, err)
363		}
364	
365		// 3. 损坏的普通文件。
366		garbage := filepath.Join(dir, "garbage.json")
367		if err := os.WriteFile(garbage, []byte("not-a-ledger{"), 0o600); err != nil {
368			t.Fatal(err)
369		}
370		if err := CreateLedger(garbage, other); KindOf(err) != ErrExists {
371			t.Fatalf("garbage file: want %s, got %v", ErrExists, err)
372		}
373		got, err := os.ReadFile(garbage)
374		if err != nil || string(got) != "not-a-ledger{" {
375			t.Fatalf("garbage file content changed: %q %v", got, err)
376		}
377	
378		// 4. 目录。
379		subdir := filepath.Join(dir, "adir")
380		if err := os.Mkdir(subdir, 0o700); err != nil {
381			t.Fatal(err)
382		}
383		if err := CreateLedger(subdir, other); KindOf(err) != ErrExists {
384			t.Fatalf("directory: want %s, got %v", ErrExists, err)
385		}
386		if fi, err := os.Stat(subdir); err != nil || !fi.IsDir() {
387			t.Fatalf("directory must remain a directory: %+v %v", fi, err)
388		}
389	
390		// 5. 悬空符号链接：拒绝；链接保留；目标文件不被创建。
391		ghostTarget := filepath.Join(dir, "ghost-ledger.json")
392		dangling := filepath.Join(dir, "dangling.json")
393		if err := os.Symlink(ghostTarget, dangling); err != nil {
394			t.Fatal(err)
395		}
396		if err := CreateLedger(dangling, other); KindOf(err) != ErrExists {
397			t.Fatalf("dangling symlink: want %s, got %v", ErrExists, err)
398		}
399		if fi, err := os.Lstat(dangling); err != nil || fi.Mode()&os.ModeSymlink == 0 {
400			t.Fatalf("dangling symlink must remain a symlink: %+v %v", fi, err)
401		}
402		if dest, err := os.Readlink(dangling); err != nil || dest != ghostTarget {
403			t.Fatalf("dangling symlink target changed: %q %v", dest, err)
404		}
405		if _, err := os.Stat(ghostTarget); !errors.Is(err, os.ErrNotExist) {
406			t.Fatalf("dangling link target must not be created, stat err=%v", err)
407		}
408	
409		// 6. 指向正常账本文件的符号链接：拒绝；链接与目标文件都不变。
410		linkToFile := filepath.Join(dir, "to-file.json")
411		if err := os.Symlink(existing, linkToFile); err != nil {
412			t.Fatal(err)
413		}
414		if err := CreateLedger(linkToFile, other); KindOf(err) != ErrExists {
415			t.Fatalf("symlink to file: want %s, got %v", ErrExists, err)
416		}
417		if dest, _ := os.Readlink(linkToFile); dest != existing {
418			t.Fatalf("file symlink target changed: %q", dest)
419		}
420		after2, _ := os.ReadFile(existing)
421		if !bytes.Equal(before, after2) {
422			t.Fatalf("symlinked ledger content must not change")
423		}
424	
425		// 7. 指向目录的符号链接：拒绝；链接保留；目标目录内不创建账本。
426		realDir2 := filepath.Join(dir, "realdir")
427		if err := os.Mkdir(realDir2, 0o700); err != nil {
428			t.Fatal(err)
429		}
430		linkToDir := filepath.Join(dir, "to-dir.json")
431		if err := os.Symlink(realDir2, linkToDir); err != nil {
432			t.Fatal(err)
433		}
434		if err := CreateLedger(linkToDir, other); KindOf(err) != ErrExists {
435			t.Fatalf("symlink to dir: want %s, got %v", ErrExists, err)
436		}
437		if dest, _ := os.Readlink(linkToDir); dest != realDir2 {
438			t.Fatalf("dir symlink target changed: %q", dest)
439		}
440		if entries, _ := os.ReadDir(realDir2); len(entries) != 0 {
441			t.Fatalf("nothing must be created behind the directory symlink: %v", entries)
442		}
443	
444		// 8. 正向：经目录符号链接在尚未占用的文件位置创建成功，
445		//    账本落在真实目录，经两条路径打开一致；之后任一路径再初始化都拒绝。
446		base := t.TempDir()
447		realD := filepath.Join(base, "real")
448		if err := os.Mkdir(realD, 0o700); err != nil {
449			t.Fatal(err)
450		}
451		dirLink := filepath.Join(base, "dirlink")
452		if err := os.Symlink(realD, dirLink); err != nil {
453			t.Fatal(err)
454		}
455		viaReal := filepath.Join(realD, "ledger.json")
456		viaLink := filepath.Join(dirLink, "ledger.json")
457		if err := CreateLedger(viaLink, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 7}}); err != nil {
458			t.Fatalf("create through directory symlink at unoccupied location: %v", err)
459		}
460		if _, err := os.Stat(viaReal); err != nil {
461			t.Fatalf("ledger must land in the real directory: %v", err)
462		}
463		l, err := Open(viaReal)
464		if err != nil {
465			t.Fatalf("open via real path: %v", err)
466		}
467		if bal, _ := l.Balance("aa", "usdc"); bal != 7 {
468			t.Fatalf("balance via real path=%d want 7", bal)
469		}
470		l2, err := Open(viaLink)
471		if err != nil {
472			t.Fatalf("open via directory symlink: %v", err)
473		}
474		if bal, _ := l2.Balance("aa", "usdc"); bal != 7 {
475			t.Fatalf("balance via symlink path=%d want 7", bal)
476		}
477		l.Close()
478		l2.Close()
479		if err := CreateLedger(viaReal, other); KindOf(err) != ErrExists {
480			t.Fatalf("re-init via real path: want %s, got %v", ErrExists, err)
481		}
482		if err := CreateLedger(viaLink, other); KindOf(err) != ErrExists {
483			t.Fatalf("re-init via symlink path: want %s, got %v", ErrExists, err)
484		}
485	}
486	
487	// 非法输入优先：即便路径已占用（含悬空符号链接），仍返回 invalid_parameter；
488	// 在空闲路径上失败时不留下任何文件，之后同一路径仍可正常初始化。
489	func TestCreateInvalidInputPrecedesOccupancyAndLeavesNothing(t *testing.T) {
490		bad := []BalanceInit{{Account: "aa", Asset: "usdc", Balance: -1}}
491	
492		// 空闲路径：非法输入不留账本、不留临时文件。
493		dir := t.TempDir()
494		path := filepath.Join(dir, "ledger.json")
495		if err := CreateLedger(path, bad); KindOf(err) != ErrInvalid {
496			t.Fatalf("want %s, got %v", ErrInvalid, err)
497		}
498		if _, err := os.Stat(path); !errors.Is(err, os.ErrNotExist) {
499			t.Fatalf("invalid init must not create ledger, stat err=%v", err)
500		}
501		assertNoTempFiles(t, dir)
502		if err := CreateLedger(path, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 3}}); err != nil {
503			t.Fatalf("valid init after rejected init: %v", err)
504		}
505	
506		// 已占用的正常账本：校验优先，返回 invalid_parameter，文件不变。
507		existing := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 500}})
508		before, _ := os.ReadFile(existing)
509		if err := CreateLedger(existing, bad); KindOf(err) != ErrInvalid {
510			t.Fatalf("invalid input must be reported before occupancy: %v", err)
511		}
512		after, _ := os.ReadFile(existing)
513		if !bytes.Equal(before, after) {
514			t.Fatalf("invalid init over existing ledger must not touch the file")
515		}
516	
517		// 悬空符号链接 + 非法输入：invalid_parameter，链接与目标状态不变。
518		base := t.TempDir()
519		target := filepath.Join(base, "ghost")
520		link := filepath.Join(base, "dangle")
521		if err := os.Symlink(target, link); err != nil {
522			t.Fatal(err)
523		}
524		if err := CreateLedger(link, bad); KindOf(err) != ErrInvalid {
525			t.Fatalf("invalid input over dangling symlink: want %s, got %v", ErrInvalid, err)
526		}
527		if fi, err := os.Lstat(link); err != nil || fi.Mode()&os.ModeSymlink == 0 {
528			t.Fatalf("symlink must remain intact after invalid init: %v", err)
529		}
530		if _, err := os.Stat(target); !errors.Is(err, os.ErrNotExist) {
531			t.Fatalf("target must not be created, stat err=%v", err)
532		}
533	}
534	
535	// 目录不可写时初始化返回 storage_error，路径上不留下账本或半成品；
536	// 恢复可写后同一路径可以正常初始化。
537	func TestCreateStorageFailureLeavesNoLedger(t *testing.T) {
538		dir := t.TempDir()
539		t.Cleanup(func() { _ = os.Chmod(dir, 0o700) })
540		path := filepath.Join(dir, "ledger.json")
541	
542		if err := os.Chmod(dir, 0o500); err != nil {
543			t.Fatal(err)
544		}
545		err := CreateLedger(path, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 1}})
546		if KindOf(err) != ErrStorage {
547			t.Fatalf("unwritable dir: want %s, got %v", ErrStorage, err)
548		}
549		if _, statErr := os.Stat(path); !errors.Is(statErr, os.ErrNotExist) {
550			t.Fatalf("storage failure must not leave a ledger file, stat err=%v", statErr)
551		}
552	
553		if err := os.Chmod(dir, 0o700); err != nil {
554			t.Fatal(err)
555		}
556		if err := CreateLedger(path, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 1}}); err != nil {
557			t.Fatalf("init after storage failure: %v", err)
558		}
559		l, err := Open(path)
560		if err != nil {
561			t.Fatalf("open after recovered init: %v", err)
562		}
563		if bal, _ := l.Balance("aa", "usdc"); bal != 1 {
564			t.Fatalf("balance=%d want 1", bal)
565		}
566		l.Close()
567	}
568	
569	// createExclusive 在路径占用时返回 ErrExists 并清理自己的临时文件，
570	// 先到的内容逐字节保留；悬空符号链接同样不留下临时文件。
571	func TestCreateExclusiveCleansTempOnOccupied(t *testing.T) {
572		dir := t.TempDir()
573		path := filepath.Join(dir, "ledger.json")
574		if err := createExclusive(path, map[string]any{"hello": "world"}); err != nil {
575			t.Fatalf("first createExclusive: %v", err)
576		}
577		before, err := os.ReadFile(path)
578		if err != nil {
579			t.Fatal(err)
580		}
581		if err := createExclusive(path, map[string]any{"hello": "other"}); KindOf(err) != ErrExists {
582			t.Fatalf("second createExclusive: want %s, got %v", ErrExists, err)
583		}
584		after, _ := os.ReadFile(path)
585		if !bytes.Equal(before, after) {
586			t.Fatalf("lost createExclusive must not rewrite the winner")
587		}
588		assertNoTempFiles(t, dir)
589	
590		ghost := filepath.Join(dir, "ghost")
591		dangling := filepath.Join(dir, "dangle")
592		if err := os.Symlink(ghost, dangling); err != nil {
593			t.Fatal(err)
594		}
595		if err := createExclusive(dangling, map[string]any{"x": 1}); KindOf(err) != ErrExists {
596			t.Fatalf("createExclusive on dangling symlink: want %s, got %v", ErrExists, err)
597		}
598		assertNoTempFiles(t, dir)
599		if _, err := os.Stat(ghost); !errors.Is(err, os.ErrNotExist) {
600			t.Fatalf("ghost target must not appear, stat err=%v", err)
601		}
602	}
603	
604	// 胜出账本正常使用期间，另一个进程的初始化“更晚结束”也不能重置
605	// 已产生的付款与退款；败者的初始余额不得混入。
606	func TestLateInitFromOtherProcessCannotResetHistory(t *testing.T) {
607		dir := t.TempDir()
608		path := filepath.Join(dir, "ledger.json")
609		if err := CreateLedger(path, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 1000}}); err != nil {
610			t.Fatal(err)
611		}
612		l, err := Open(path)
613		if err != nil {
614			t.Fatal(err)
615		}
616		defer l.Close()
617	
618		submit := func(id string, amount int64) {
619			t.Helper()
620			res, err := l.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{intent(id, "aa", "usdc", amount)}})
621			if err != nil {
622				t.Fatalf("submit %s: %v", id, err)
623			}
624			if res.Results[0].Status != StatusSettled {
625				t.Fatalf("submit %s: %+v", id, res.Results[0])
626			}
627		}
628		refund := func(id, settlement string) {
629			t.Helper()
630			res, err := l.Refund(RefundBatch{Refunds: []RefundRequest{{ID: id, SettlementID: settlement, Reason: "cancel"}}})
631			if err != nil {
632				t.Fatalf("refund %s: %v", id, err)
633			}
634			if res.Results[0].Status != StatusRefundSuccess {
635				t.Fatalf("refund %s: %+v", id, res.Results[0])
636			}
637		}
638	
639		submit("p1", 100) // 900
640		refund("r1", "p1")
641	
642		// 启动另一个进程的初始化，先挡在闸门前，让它“开始得早、结束得晚”。
643		exe, err := os.Executable()
644		if err != nil {
645			t.Fatal(err)
646		}
647		work := t.TempDir()
648		gate := filepath.Join(work, "gate")
649		result := filepath.Join(work, "result")
650		cmd := exec.Command(exe, "-test.run=^TestHelperCreateProcess$", "-test.count=1")
651		cmd.Env = append(os.Environ(),
652			helperEnv+"=1",
653			envLedger+"="+path,
654			envInitIdx+"=99",
655			envGate+"="+gate,
656			envResult+"="+result,
657		)
658		if err := cmd.Start(); err != nil {
659			t.Fatal(err)
660		}
661		time.Sleep(150 * time.Millisecond) // 确认它已在等待
662	
663		// 胜出方继续产生付款与退款。
664		submit("p2", 200) // 700
665		refund("r2", "p2")
666		submit("p3", 50) // 950
667	
668		// 放行较晚结束的初始化：它必须失败，不能把账本重置成新余额。
669		if err := os.WriteFile(gate, []byte("go"), 0o600); err != nil {
670			t.Fatal(err)
671		}
672		if err := cmd.Wait(); err == nil {
673			t.Fatalf("late init must exit non-zero")
674		} else if ee, ok := err.(*exec.ExitError); !ok || ee.ExitCode() != 1 {
675			t.Fatalf("late init exit: %v", err)
676		}
677		res, _ := os.ReadFile(result)
678		if string(res) != "err:"+ErrExists {
679			t.Fatalf("late init result=%q want err:%s", res, ErrExists)
680		}
681	
682		snap, err := l.Query()
683		if err != nil {
684			t.Fatal(err)
685		}
686		if bal, _ := l.Balance("aa", "usdc"); bal != 950 {
687			t.Fatalf("balance reset by late init: %d want 950", bal)
688		}
689		if bal, _ := l.Balance("winner-99", "usdc"); bal != 0 {
690			t.Fatalf("loser balances must not leak into winner ledger: %d", bal)
691		}
692		if len(snap.Settlements) != 3 || len(snap.Refunds) != 2 {
693			t.Fatalf("history reset: settlements=%d refunds=%d", len(snap.Settlements), len(snap.Refunds))
694		}
695		if got := []string{snap.Settlements[0].ID, snap.Settlements[1].ID, snap.Settlements[2].ID}; got[0] != "p1" || got[1] != "p2" || got[2] != "p3" {
696			t.Fatalf("settlements order/content: %v", got)
697		}
698		assertNoTempFiles(t, dir)
699	
700		// 被打扰之后付款与退款仍能正常更新余额与历史。
701		submit("p4", 30)
702		if bal, _ := l.Balance("aa", "usdc"); bal != 920 {
703			t.Fatalf("balance after further payment=%d want 920", bal)
704		}
705		refund("r4", "p4")
706		if bal, _ := l.Balance("aa", "usdc"); bal != 950 {
707			t.Fatalf("balance after further refund=%d want 950", bal)
708		}
709		snap, _ = l.Query()
710		if len(snap.Settlements) != 4 || len(snap.Refunds) != 3 {
711			t.Fatalf("history after further ops: settlements=%d refunds=%d", len(snap.Settlements), len(snap.Refunds))
712		}
713	}
